import bpy,json,hashlib,math,numpy as np
from pathlib import Path
from mathutils import Vector
root=Path(bpy.data.filepath).parents[1];cap=root/'captures/shipyard_setback_20261116';craft=bpy.data.collections['Shipyard_COMBINED_Craft']
assert not bpy.data.is_dirty
def digest(o):
 h=hashlib.sha256();h.update(np.array(o.matrix_world,dtype=np.float64).tobytes())
 if o.type=='MESH':
  for attr,size,prop in [(o.data.vertices,3,'co'),(o.data.loops,1,'vertex_index')]:
   a=np.empty(len(attr)*size,np.float64 if prop=='co' else np.int32);attr.foreach_get(prop,a);h.update(a.tobytes())
  for uv in o.data.uv_layers:
   a=np.empty(len(uv.data)*2,np.float32);uv.data.foreach_get('uv',a);h.update(a.tobytes())
  h.update(json.dumps([m.name if m else '' for m in o.data.materials]).encode())
 return h.hexdigest()
rows=[]
for o in craft.objects:
 pts=[o.matrix_world@Vector(v) for v in o.bound_box]
 rows.append({'name':o.name,'min':[min(v[i] for v in pts) for i in range(3)],'max':[max(v[i] for v in pts) for i in range(3)],'hash':digest(o),'materials':[m.name for m in o.data.materials if m] if hasattr(o.data,'materials') else []})
(cap/'source_before.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2),encoding='utf8')
bank=bpy.data.objects['M14 continuous sculpted shore bank']
from mathutils.bvhtree import BVHTree
oldtree=BVHTree.FromPolygons([bank.matrix_world@v.co for v in bank.data.vertices],[list(p.vertices) for p in bank.data.polygons])
def sm(a,b,x):
 t=max(0,min(1,(x-a)/(b-a)));return t*t*(3-2*t)
def shore(z):return 8+2*math.sin(z*.14)+.6*math.sin(z*.37+.4)+2.2*math.exp(-((z+2.5)/3.6)**2)-.85*math.exp(-((z-2.5)/2.34)**2)
def baseheight(x,y,ox=12.35):
 a=math.radians(-81.5);wx=ox+math.cos(a)*x-math.sin(a)*y;wz=34-math.sin(a)*x-math.cos(a)*y;off=wx-shore(wz)
 if off<0:
  d=-off;return -.11*d-.013*d*d/(1+d*.025)
 return min(off*.2,.7)+sm(2,14,off)*(.2+math.sin(wz*.21)*.16)
matrices={o.name:o.matrix_world.copy() for o in craft.objects}
bpy.app.driver_namespace['setback16']={'root':root,'cap':cap,'craft':craft,'bank':bank,'digest':digest,'old_ground_tree':oldtree,'old_matrices':matrices,'sm':sm,'shore':shore,'baseheight':baseheight}
