for row in rows:
 n=row['name']
 if any(k in n for k in ['cradle','boat support','boat trestle','boat keel','timber repair boat Keel','inner access','boat stair','basin foundation','ramp bearer','hull shore','boat ladder']):print(n,row['min'],row['max'])
